CREATE TABLE IF NOT EXISTS v203_improvements(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),unit int NOT NULL,kind text NOT NULL,objective text NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','confirmed','implemented','closed','rejected')),evidence jsonb NOT NULL,suggestion text NOT NULL,measure text NOT NULL DEFAULT '',teacher_note text NOT NULL DEFAULT '',targets jsonb NOT NULL DEFAULT '[]',rule jsonb NOT NULL,result jsonb NOT NULL DEFAULT '{}',next_action text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,implemented_at timestamptz,closed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS v203_open_improvement ON v203_improvements(class_id,unit,kind) WHERE state IN ('draft','confirmed','implemented');
CREATE TABLE IF NOT EXISTS v203_plans(id text PRIMARY KEY,loop_id text NOT NULL REFERENCES v202_loops(id),class_id text NOT NULL REFERENCES classes(id),student_id text NOT NULL REFERENCES users(id),objective text NOT NULL,unit int NOT NULL,kind text NOT NULL,stage text NOT NULL CHECK(stage IN ('day3','day7','post')),improvement_id text REFERENCES v203_improvements(id),origin_key text NOT NULL UNIQUE,origin_revision text NOT NULL,baseline jsonb NOT NULL,rule jsonb NOT NULL,due_at timestamptz NOT NULL,original_due_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'scheduled' CHECK(state IN ('scheduled','preparing','ready','submitted','grading','graded','review','generation_error')),valid boolean NOT NULL DEFAULT true,hold_reason text NOT NULL DEFAULT '',teacher_approved boolean NOT NULL DEFAULT false,questions jsonb NOT NULL DEFAULT '[]',answers jsonb NOT NULL DEFAULT '{}',marks jsonb NOT NULL DEFAULT '[]',score numeric,outcome text,quality jsonb NOT NULL DEFAULT '{}',error text NOT NULL DEFAULT '',generation_tries int NOT NULL DEFAULT 0,grading_tries int NOT NULL DEFAULT 0,lease_token text,lease_at timestamptz,retry_at timestamptz NOT NULL DEFAULT now(),defer_request text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,graded_at timestamptz);
ALTER TABLE v203_plans ADD COLUMN IF NOT EXISTS opened_at timestamptz;
CREATE INDEX IF NOT EXISTS v203_due ON v203_plans(state,due_at,retry_at);
CREATE INDEX IF NOT EXISTS v203_class_goal ON v203_plans(class_id,unit,kind,student_id);
CREATE TABLE IF NOT EXISTS v203_events(id text PRIMARY KEY,plan_id text REFERENCES v203_plans(id),improvement_id text REFERENCES v203_improvements(id),actor_id text NOT NULL,action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS v203_event_plan ON v203_events(plan_id,created_at);
CREATE TABLE IF NOT EXISTS v203_worker(id int PRIMARY KEY CHECK(id=1),lease_token text,lease_until timestamptz,last_started timestamptz,last_finished timestamptz,last_error text NOT NULL DEFAULT '');
INSERT INTO v203_worker(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE OR REPLACE VIEW v203_evidence AS
SELECT 'original:'||d.attempt_id||':'||(g->>'key') AS evidence_id,a.class_id,c.name AS class_name,t.student_user_id AS student_id,u.display_name AS student_name,(g->>'unit')::int AS unit,g->>'kind' AS kind,g->>'objective' AS objective,'original'::text AS stage,'graded'::text AS status,(g->>'percent')::numeric AS score,CASE WHEN (g->>'weak')::boolean THEN 'needs_support' ELSE 'retained' END AS outcome,NOT COALESCE(j.pending,false) AS valid,d.updated_at AS at,(g->>'count')::int AS question_count,l.id AS loop_id,d.attempt_id AS source_id,COALESCE((g->'questions')::text,'') AS feedback
FROM v202_diagnostics d JOIN v20_attempts t ON t.id=d.attempt_id JOIN v20_assessments a ON a.id=t.assessment_id JOIN classes c ON c.id=a.class_id JOIN users u ON u.id=t.student_user_id LEFT JOIN v202_jobs j ON j.attempt_id=t.id CROSS JOIN LATERAL jsonb_array_elements(d.summary->'groups') g LEFT JOIN v202_loops l ON l.attempt_id=t.id AND l.skill_key=g->>'key'
UNION ALL
SELECT s.id,a.class_id,c.name,t.student_user_id,u.display_name,l.unit,l.kind,l.objective,CASE WHEN s.stage='verify' THEN 'immediate' ELSE 'practice' END,s.status,s.score,CASE WHEN s.score>=80 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.marks) m WHERE (m->>'score')::numeric<3 OR (m->>'uncertain')::boolean) THEN 'retained' ELSE 'needs_support' END,NOT l.source_changed AND NOT EXISTS(SELECT 1 FROM v202_jobs j WHERE j.attempt_id=l.attempt_id AND j.pending),COALESCE(s.graded_at,s.created_at),jsonb_array_length(s.questions),l.id,s.id,COALESCE(s.marks::text,'')
FROM v202_steps s JOIN v202_loops l ON l.id=s.loop_id JOIN v20_attempts t ON t.id=l.attempt_id JOIN v20_assessments a ON a.id=t.assessment_id JOIN classes c ON c.id=a.class_id JOIN users u ON u.id=t.student_user_id
UNION ALL
SELECT p.id,p.class_id,c.name,p.student_id,u.display_name,p.unit,p.kind,p.objective,p.stage,p.state,p.score,p.outcome,p.valid AND NOT EXISTS(SELECT 1 FROM v202_loops l JOIN v202_jobs j ON j.attempt_id=l.attempt_id WHERE l.id=p.loop_id AND j.pending),COALESCE(p.graded_at,p.created_at),jsonb_array_length(p.questions),p.loop_id,p.id,COALESCE(p.marks::text,'') FROM v203_plans p JOIN classes c ON c.id=p.class_id JOIN users u ON u.id=p.student_id;
